const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-photographer-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-photographer-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
