    }

    function init(root = document) {
        within(root, '[data-custom-sheet]').forEach((el) => {
            if (!mounted.has(el)) mounted.set(el, sheet(el));
        });
    }

    function destroy(root = document) {
        within(root, '[data-custom-sheet]').forEach((el) => {
            mounted.get(el)?.();
            mounted.delete(el);
        });
    }

    reduced.addEventListener('change', () => {
        destroy();
        init();
    });

